def nomination(f,evidence):
 p=BASE/f/('location_certificate.hpp' if f=='emg' else 'cert.hpp' if f=='ht' else 'certificate.hpp' if f=='ztnbinom' else 'mle.hpp');lines=p.read_text().splitlines();needle,fix=NOTES.get(f,('', ''))
 hits=[i+1 for i,s in enumerate(lines) if needle and needle in s and not s.lstrip().startswith('//')]
 if not hits:
  hits=[i+1 for i,s in enumerate(lines) if re.search(r'inline .*\b(?:'+re.escape(f)+r'_mle|fit_|.*_mle)\s*\(',s)]
 line=hits[0] if hits else 1
 if not fix:
  fix=('The observed returned point misses an isolated high-precision stationary reference. Replace step/objective-only acceptance with a relative public-coefficient enclosure (monotone bracket or score/information bound), propagate transformations, and return a numerical failure when the requested width is unresolved. The exact causal arithmetic operation remains open; the executed fitter entry is the source nomination.' if evidence.startswith('stationary') else 'Reevaluate the original-data likelihood and feasibility before accepting the proposal; complete the relevant score/face coverage or stop when it is unresolved. The executed fitter entry is identified, while the exact causal arithmetic operation remains open.')
 path=str(p.relative_to(ROOT))
 return dict(path=path,line=line,snippet=lines[line-1].strip(),likely_fix=fix,attribution='arithmetic seam reviewed; fix remains a hypothesis' if f in NOTES else 'executed fitter entry; exact causal operation open')
